mapper.update:
UPDATE ddc_config_workload_observation SET observed_at = #{row.observedAt}, valid_until = #{row.validUntil},
    recorded_at = #{row.recordedAt}, view_json = #{row.viewJson,jdbcType=OTHER,typeHandler=top.egon.cola.component.tianshu.admin.dao.typehandler.DdcJsonbTypeHandler},
    update_user_id = #{row.updateUserId}, update_time = #{row.updateTime}, version = version + 1
WHERE tenant_id = #{row.tenantId} AND id = #{row.id} AND version = #{expectedVersion} AND deleted_at IS NULL
    AND target_binding_id = #{row.targetBindingId} AND target_revision = #{row.targetRevision}
    AND cluster_id = #{row.clusterId} AND k8s_namespace = #{row.k8sNamespace} AND workload_uid = #{row.workloadUid}
    AND (view_json ->> 'writerEpoch')::bigint = #{expectedEpoch}
    AND (view_json ->> 'reportSeq')::bigint = #{expectedSeq}
    AND ((#{row.viewJson,jdbcType=OTHER,typeHandler=top.egon.cola.component.tianshu.admin.dao.typehandler.DdcJsonbTypeHandler} ->> 'writerEpoch')::bigint > #{expectedEpoch}
        OR ((#{row.viewJson,jdbcType=OTHER,typeHandler=top.egon.cola.component.tianshu.admin.dao.typehandler.DdcJsonbTypeHandler} ->> 'writerEpoch')::bigint = #{expectedEpoch}
            AND (#{row.viewJson,jdbcType=OTHER,typeHandler=top.egon.cola.component.tianshu.admin.dao.typehandler.DdcJsonbTypeHandler} ->> 'reportSeq')::bigint > #{expectedSeq}))
